from typing import Optional, List
from collections import deque

class TreeNode:
    def __init__(self, val=0, left=None, right=None):
        self.val = val
        self.left = left
        self.right = right

def max_depth(root: Optional[TreeNode]) -> int:
    if not root:
        return 0
    queue = deque([(root, 1)])
    max_d = 0
    while queue:
        node, d = queue.popleft()
        max_d = max(max_d, d)
        if node.left:
            queue.append((node.left, d+1))
        if node.right:
            queue.append((node.right, d+1))
    return max_d
```
BFS with type hints. Queue can hold O(n) nodes in worst case.

