package main

import (
    "fmt"
    "os"
    "path/filepath"
    "strings"
)

func SafeRead(relPath string) ([]byte, error) {
    base := "/var/www/uploads"
    // Clean the path and ensure it stays under base
    requested := filepath.Join(base, relPath)
    cleaned := filepath.Clean(requested)

    // Verify no traversal escaped the base directory
    if !strings.HasPrefix(cleaned, base) {
        return nil, fmt.Errorf("path traversal detected")
    }

    // Resolve symlinks and re-check
    resolved, err := filepath.EvalSymlinks(cleaned)
    if err != nil {
        return nil, err
    }
    if !strings.HasPrefix(resolved, base) {
        return nil, fmt.Errorf("symlink traversal detected")
    }

    return os.ReadFile(resolved)
}
```
This joins, cleans, validates the prefix, then resolves symlinks and validates again.

