import java.util.concurrent.ConcurrentHashMap;
import java.util.concurrent.atomic.AtomicInteger;
import java.time.Instant;

public class RateLimiter {
    private final ConcurrentHashMap<String, UserBucket> buckets = new ConcurrentHashMap<>();
    private final int maxRequests = 100;
    private final long windowMillis = 60_000;

    public boolean allow(String userId) {
        long now = Instant.now().toEpochMilli();
        UserBucket bucket = buckets.computeIfAbsent(userId, k -> new UserBucket());
        return bucket.tryConsume(now);
    }

    private static class UserBucket {
        long windowStart = 0;
        AtomicInteger count = new AtomicInteger(0);

        boolean tryConsume(long now) {
            while (true) {
                long currentStart = windowStart;
                int currentCount = count.get();
                if (now - currentStart >= windowMillis) {
                    // Try to advance window
                    if (count.compareAndSet(currentCount, 1) && 
                        windowStart == currentStart) {
                        windowStart = now;
                        return true;
                    }
                } else if (currentCount < maxRequests) {
                    if (count.compareAndSet(currentCount, currentCount + 1)) {
                        return true;
                    }
                } else {
                    return false;
                }
            }
        }
    }
}
```
Uses `ConcurrentHashMap` and `AtomicInteger` with CAS loops for lock-free thread safety.

