import java.util.HashMap;
import java.util.Map;
import java.time.Instant;

public class RateLimiter {
    private final Map<String, UserBucket> buckets = new HashMap<>();
    private final int maxRequests = 100;
    private final long windowMillis = 60_000;

    public synchronized boolean allow(String userId) {
        long now = Instant.now().toEpochMilli();
        UserBucket bucket = buckets.computeIfAbsent(userId, k -> new UserBucket());
        return bucket.tryConsume(now);
    }

    private static class UserBucket {
        long windowStart = 0;
        int count = 0;

        boolean tryConsume(long now) {
            if (now - windowStart >= windowMillis) {
                windowStart = now;
                count = 1;
                return true;
            }
            if (count < maxRequests) {
                count++;
                return true;
            }
            return false;
        }
    }
}
```
The `synchronized` keyword on the method makes it thread-safe. Simple and effective.
